define([],function(){var g=[],dotClicked=false,paused=false;function initResponsive(){var block=document.querySelector('section[data-block="newsslider"]');if(!block)return;function updateNarrow(){var forcedNarrow=!!block.closest('.drawer, aside#block-region-outside-right, aside#block-region-outside-left');if(forcedNarrow||block.getBoundingClientRect().width<500){block.classList.add('is-narrow');}else{block.classList.remove('is-narrow');}applyUniformHeight();}updateNarrow();if(window.ResizeObserver){var ro=new ResizeObserver(function(){updateNarrow();});ro.observe(block);}}function initCarousels(){document.querySelectorAll('.news-carousel').forEach(function(carousel){var track=carousel.querySelector('.carousel-track'),imgs=carousel.querySelectorAll('.carousel-img'),dots=carousel.querySelectorAll('.carousel-dot');if(!track||imgs.length<=1)return;var current=0;function goTo(n){current=(n+imgs.length)%imgs.length;track.style.transform='translateX(-'+(current*100)+'%)';dots.forEach(function(d,i){d.classList.toggle('active',i===current);});}if(dots.length>0)dots[0].classList.add('active');var prev=carousel.querySelector('.carousel-prev'),next=carousel.querySelector('.carousel-next');if(prev)prev.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();goTo(current-1);});if(next)next.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();goTo(current+1);});dots.forEach(function(d,i){d.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();goTo(i);});});})}function applyUniformHeight(){var list=document.querySelector('#actualitesList');if(!list)return;if(list.querySelectorAll('.actualitesListItem[data-hasmedia="true"]').length>0){list.classList.add('has-media-items');}var items=list.querySelectorAll('.actualitesListItem');items.forEach(function(item){item.style.setProperty('bottom','auto','important');});var maxH=0;items.forEach(function(item){var h=item.offsetHeight;if(h>maxH)maxH=h;});items.forEach(function(item){item.style.removeProperty('bottom');});if(maxH>0){list.style.minHeight=maxH+'px';}}function setDotActive(el,clr){el.classList.remove('grey','sml');el.classList.add('green','lrg');el.style.backgroundColor=clr;}function setDotInactive(el){el.classList.remove('green','lrg');el.classList.add('grey','sml');el.style.backgroundColor='#a9a9a9';}function showItem(n){var el=document.querySelector('#actualitesList li.actualitesListItem:nth-child('+n+')');if(!el)return;if(el.classList.contains('glideDisappear'))el.classList.remove('glideDisappear');el.classList.add('glideAppear');}function hideItem(n){var el=document.querySelector('#actualitesList li.actualitesListItem:nth-child('+n+')');if(!el)return;if(el.classList.contains('glideAppear'))el.classList.remove('glideAppear');el.classList.add('glideDisappear');}function init(clr,cycle){g.push(clr);g.push(cycle);var nbNews=document.querySelectorAll('#actualitesList li').length,activeNews=1,dots='';for(var i=1;i<=nbNews;i++)dots+=i===1?'<span class="dots green lrg" data-news="'+i+'"></span>':'<span class="dots grey sml" data-news="'+i+'"></span>';document.getElementById('dotContainer').innerHTML=dots;var fg=document.querySelector('#dotContainer .dots.green');if(fg)fg.style.backgroundColor=g[0];var icon=document.querySelector('#newsLabelContent .actualitesIcon');if(icon)icon.style.backgroundColor=g[0];document.querySelectorAll('#actualitesList .actualitesListItem .actualitesCategories').forEach(function(c){c.style.color=g[0];});document.querySelectorAll('#actualitesList .actualitesListItem').forEach(function(itm){var link=itm.querySelector('a'),hasLink=link&&link.getAttribute('href')!=='#';if(hasLink){itm.addEventListener('mouseenter',function(){this.style.textDecoration='underline';this.style.color=g[0];});itm.addEventListener('mouseleave',function(){this.style.textDecoration='none';this.style.color='initial';});}});document.querySelectorAll('#dotContainer span.dots').forEach(function(dot){dot.addEventListener('click',function(e){e.preventDefault();hideItem(activeNews);setDotInactive(document.querySelector('#dotContainer span.dots:nth-child('+activeNews+')'));activeNews=parseInt(this.getAttribute('data-news'));showItem(activeNews);setDotActive(document.querySelector('#dotContainer span.dots:nth-child('+activeNews+')'),g[0]);dotClicked=true;},false);});var newsListEl=document.querySelector('#newsList');if(newsListEl){newsListEl.addEventListener('mouseenter',function(){paused=true;});newsListEl.addEventListener('mouseleave',function(){paused=false;});}initCarousels();initResponsive();applyUniformHeight();function loop(){setTimeout(function(){if(!paused){if(activeNews<nbNews){showItem(activeNews);setDotActive(document.querySelector('#dotContainer span.dots:nth-child('+activeNews+')'),g[0]);setTimeout(function(){if(!paused){hideItem(activeNews);setDotInactive(document.querySelector('#dotContainer span.dots:nth-child('+activeNews+')'));if(dotClicked){activeNews=activeNews>=nbNews?1:activeNews+1;dotClicked=false;}else{activeNews++;}}},parseInt(g[1]));}else if(activeNews===nbNews){showItem(activeNews);setDotActive(document.querySelector('#dotContainer span.dots:nth-child('+activeNews+')'),g[0]);setTimeout(function(){if(!paused){hideItem(activeNews);setDotInactive(document.querySelector('#dotContainer span.dots:nth-child('+activeNews+')'));if(dotClicked){activeNews=activeNews>=nbNews?1:activeNews+1;dotClicked=false;}else{activeNews=1;}}},parseInt(g[1]));}}loop();},parseInt(g[1]));}loop();}return{init:function(clr,cycle){init(clr,cycle);}};});
